<h1 class="page-title">Khám phá sản phẩm</h1><div class="catalog-layout"><aside><form class="panel" action="/products"><h2>Bộ lọc</h2><label class="form-label" for="filter-q">Từ khóa</label><input class="form-control" id="filter-q" name="q" value="<?= e($filters['q']??'') ?>"><label class="form-label" for="filter-category">Loại thiết bị</label><select class="form-select" id="filter-category" name="category"><option value="">Tất cả</option><?php foreach($categories as $c):?><option value="<?= $c['id'] ?>" <?= ($filters['category']??'')==$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach?></select><label class="form-label" for="filter-brand">Thương hiệu</label><select class="form-select" id="filter-brand" name="brand"><option value="">Tất cả</option><?php foreach($brands as $b):?><option value="<?= $b['id'] ?>" <?= ($filters['brand']??'')==$b['id']?'selected':'' ?>><?= e($b['name']) ?></option><?php endforeach?></select><label class="form-label" for="filter-min">Giá từ (₫)</label><input class="form-control" id="filter-min" name="min" type="number" min="0" value="<?= e($filters['min']??'') ?>"><label class="form-label" for="filter-max">Giá đến (₫)</label><input class="form-control" id="filter-max" name="max" type="number" min="0" value="<?= e($filters['max']??'') ?>"><label class="form-label" for="filter-sort">Sắp xếp</label><select class="form-select" id="filter-sort" name="sort"><?php foreach(['newest'=>'Mới nhất','price_asc'=>'Giá tăng dần','price_desc'=>'Giá giảm dần'] as $k=>$v):?><option value="<?= $k ?>" <?= ($filters['sort']??'newest')===$k?'selected':'' ?>><?= $v ?></option><?php endforeach?></select><button class="btn btn-primary w-100 mt-3" type="submit" id="apply-filters">Áp dụng bộ lọc</button><a href="/products" class="btn btn-light w-100 mt-2">Xóa bộ lọc</a></form></aside><section><p class="muted mb-3"><?= $count ?> sản phẩm phù hợp</p><div class="product-grid"><?php foreach($products as $p){require __DIR__.'/card.php';}?></div><?php if(!$products):?><div class="panel empty">Không có sản phẩm phù hợp. Thử thay đổi bộ lọc.</div><?php endif?><nav class="d-flex gap-2 mt-4" aria-label="Phân trang"><?php for($i=1;$i<=$pages;$i++):?><a class="btn <?= $i===$page?'btn-primary':'btn-light' ?>" href="/products?<?= e(http_build_query(array_merge($filters,['page'=>$i]))) ?>"><?= $i ?></a><?php endfor?></nav></section></div>
